from __future__ import annotations

import os
import sys
from importlib import import_module
from pathlib import Path
from types import ModuleType

import pytest
from fastapi import FastAPI, Request
from fastapi.testclient import TestClient

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from request_guard import reject_request

from leviathan_api.main import create_app
from leviathan_vault import app_credentials
from leviathan_vault.app_credentials import InMemoryCredentialStore

# Generated by the desktop build; these tests import but never run configure_data.
build_constants = ModuleType("build_constants")
build_constants.RISK_LOCK_SHA256 = "0" * 64
sys.modules.setdefault("build_constants", build_constants)
leviathan_desktop = import_module("leviathan_desktop")

PORT = 49123
ORIGIN = f"http://127.0.0.1:{PORT}"
CAPABILITY = "a" * 64


def make_client() -> TestClient:
    desktop = FastAPI()

    @desktop.middleware("http")
    async def guard(request: Request, call_next):
        rejected = reject_request(request, capability=CAPABILITY, port=PORT)
        return rejected if rejected is not None else await call_next(request)

    desktop.mount("/api", create_app(credential_store=InMemoryCredentialStore()))
    return TestClient(desktop, base_url=ORIGIN)


def test_mounted_credentials_path_has_single_api_prefix() -> None:
    with make_client() as client:
        headers = {"X-Leviathan-Capability": CAPABILITY}
        response = client.get("/api/live-trading/credentials", headers=headers)
        assert response.status_code == 200
        assert response.headers["cache-control"] == "no-store"
        assert client.get("/api/api/live-trading/credentials", headers=headers).status_code == 404


def test_real_credentials_router_is_behind_desktop_capability() -> None:
    with make_client() as client:
        path = "/api/live-trading/credentials"
        assert client.get(path).status_code == 403
        assert client.get(path, headers={"X-Leviathan-Capability": "b" * 64}).status_code == 403
        assert client.get(path, headers={"X-Leviathan-Capability": CAPABILITY}).status_code == 200


def test_wrong_mutation_origin_and_host_are_denied() -> None:
    with make_client() as client:
        path = "/api/live-trading/credentials/ALPACA/PAPER/default"
        headers = {"X-Leviathan-Capability": CAPABILITY}
        denied_origin = client.put(
            path,
            headers={**headers, "Origin": "https://evil.invalid"},
            json={"key_id": "SYNTHETIC-key-0001", "secret_key": "SYNTHETIC-secret-0002"},
        )
        assert denied_origin.status_code == 403
        denied_host = client.get(
            "/api/live-trading/credentials", headers={**headers, "Host": "localhost:49123"}
        )
        assert denied_host.status_code == 421


def test_runtime_store_uses_injected_local_app_data_root(tmp_path, monkeypatch) -> None:
    roots: list[Path] = []

    class FakeStore:
        def __init__(self, root: Path) -> None:
            roots.append(root)

    monkeypatch.setattr(app_credentials, "DPAPICredentialStore", FakeStore)
    monkeypatch.setenv("LOCALAPPDATA", str(tmp_path))
    store = leviathan_desktop._runtime_credential_store()
    assert isinstance(store, FakeStore)
    assert roots == [tmp_path / "Leviathan AI" / "credentials"]


def test_runtime_store_fails_closed_without_local_app_data(monkeypatch) -> None:
    monkeypatch.setattr(os, "environ", {})
    with pytest.raises(RuntimeError, match="LOCALAPPDATA is required"):
        leviathan_desktop._runtime_credential_store()
